"""Tests for bulk discount functionality."""

from decimal import Decimal

import pytest

from pricing import LineItem
from pricing.bulk_discount import (
    BULK_DISCOUNT_PERCENT,
    BULK_QUANTITY_THRESHOLD,
    calculate_bulk_discount,
    qualifies_for_bulk_discount,
)


class TestQualifiesForBulkDiscount:
    """Tests for qualifies_for_bulk_discount (Req 1.1, 1.2, 1.3)."""

    @pytest.mark.l4("C-8764baca", "C-e4015f6b", "C-4284227d")
    def test_quantity_10_qualifies(self):
        """WHEN a line item has a quantity of exactly 10 THEN it qualifies for bulk discount."""
        item = LineItem("apple", Decimal("1.00"), 10)
        assert qualifies_for_bulk_discount(item) is True

    @pytest.mark.l4("C-8764baca", "C-e4015f6b")
    def test_quantity_greater_than_10_qualifies(self):
        """WHEN a line item has a quantity greater than 10 THEN it qualifies for bulk discount."""
        item = LineItem("apple", Decimal("1.00"), 11)
        assert qualifies_for_bulk_discount(item) is True

    @pytest.mark.l4("C-4284227d")
    def test_quantity_9_does_not_qualify(self):
        """WHEN a line item has a quantity of 9 or fewer THEN it does not qualify."""
        item = LineItem("apple", Decimal("1.00"), 9)
        assert qualifies_for_bulk_discount(item) is False

    @pytest.mark.l4("C-4284227d")
    def test_quantity_1_does_not_qualify(self):
        """WHEN a line item has quantity 1 THEN it does not qualify."""
        item = LineItem("apple", Decimal("1.00"), 1)
        assert qualifies_for_bulk_discount(item) is False


class TestCalculateBulkDiscount:
    """Tests for calculate_bulk_discount (Req 1.4)."""

    @pytest.mark.l4("C-1caf4da3")
    def test_discount_is_5_percent_of_total(self):
        """Discount equals 5% of line total for qualifying items."""
        item = LineItem("apple", Decimal("10.00"), 10)
        discount = calculate_bulk_discount(item)
        expected = Decimal("10.00") * Decimal("0.05")
        assert discount == expected

    @pytest.mark.l4("C-1caf4da3")
    def test_round_half_up(self):
        """Discount is rounded half-up to 0.01."""
        # 10 items at $0.025 each = $0.25 total, 5% = $0.0125 -> rounds to $0.01
        item = LineItem("apple", Decimal("0.025"), 10)
        discount = calculate_bulk_discount(item)
        assert discount == Decimal("0.01")

    @pytest.mark.l4("C-1caf4da3")
    def test_round_half_up_with_0_125(self):
        """Rounding behavior with amounts that require half-up rounding (e.g., 0.125 -> 0.13)."""
        # 10 items at $0.026 each = $0.26 total, 5% = $0.013 -> rounds to $0.01
        # 10 items at $0.027 each = $0.27 total, 5% = $0.0135 -> rounds to $0.01
        # Need an example that rounds up: $0.125 should round to $0.13
        # 5% of $2.50 = $0.125 -> should round to $0.13
        item = LineItem("apple", Decimal("0.25"), 10)
        discount = calculate_bulk_discount(item)
        assert discount == Decimal("0.13")

    @pytest.mark.l4("C-1caf4da3")
    def test_non_qualifying_returns_zero(self):
        """Non-qualifying items return zero discount."""
        item = LineItem("apple", Decimal("10.00"), 9)
        discount = calculate_bulk_discount(item)
        assert discount == Decimal("0.00")

    @pytest.mark.l4("C-1caf4da3")
    def test_quantity_10_exact_5_percent(self):
        """Exact 5% calculation without rounding needed."""
        item = LineItem("apple", Decimal("100.00"), 10)
        discount = calculate_bulk_discount(item)
        assert discount == Decimal("5.00")


class TestBulkDiscountConstants:
    """Test the module constants."""

    def test_bulk_quantity_threshold(self):
        """Bulk quantity threshold is 10."""
        assert BULK_QUANTITY_THRESHOLD == 10

    def test_bulk_discount_percent(self):
        """Bulk discount percent is 5."""
        assert BULK_DISCOUNT_PERCENT == Decimal("5")

